-- Ngân hàng câu hỏi trắc nghiệm/dịch lệnh CNC do giáo viên tự quản lý.
-- Thay thế nội dung hard-code trong services/cnc-lms.ts (CNC_GATE_QUIZ,
-- CNC_LESSON_2_QUIZ, CNC_LESSON_3_QUIZ, CNC_TURN/MILL_COMMAND_TRANSLATION_QUIZ)
-- và bổ sung Bài tập 3 mới (dịch lệnh trả lời ngắn, chấm theo từ khóa) cho Bài 2 & Bài 3.
-- Chạy sau docs/supabase-schema.sql.

create table if not exists public.cnc_quiz_questions (
  id text primary key,
  quiz_key text not null,
  question_type text not null default 'multiple_choice'
    check (question_type in ('multiple_choice', 'short_answer')),
  question text not null,
  options jsonb,               -- multiple_choice: string[] (4 lựa chọn)
  correct_index int,           -- multiple_choice: chỉ số đáp án đúng trong options
  keywords jsonb,               -- short_answer: string[] từ khóa cần có trong câu trả lời
  min_keyword_matches int,      -- short_answer: số từ khóa tối thiểu để coi là đúng (chấm gần đúng)
  explanation text not null default '',
  order_index int not null default 0,
  updated_by uuid references public.profiles (id),
  updated_at timestamptz not null default now(),
  constraint cnc_quiz_questions_mc_shape check (
    question_type <> 'multiple_choice' or (options is not null and correct_index is not null)
  ),
  constraint cnc_quiz_questions_sa_shape check (
    question_type <> 'short_answer' or (keywords is not null and min_keyword_matches is not null)
  )
);

create index if not exists cnc_quiz_questions_quiz_key_idx
  on public.cnc_quiz_questions (quiz_key, order_index);

alter table public.cnc_quiz_questions enable row level security;

-- Học sinh đã đăng nhập đọc được toàn bộ ngân hàng câu hỏi để làm bài.
drop policy if exists "authenticated read cnc quiz questions" on public.cnc_quiz_questions;
create policy "authenticated read cnc quiz questions"
  on public.cnc_quiz_questions for select to authenticated
  using (true);

-- Chỉ giáo viên/quản trị (role = 'admin') được thêm/sửa/xóa câu hỏi.
drop policy if exists "admin manage cnc quiz questions" on public.cnc_quiz_questions;
create policy "admin manage cnc quiz questions"
  on public.cnc_quiz_questions for all to authenticated
  using (public.is_admin())
  with check (public.is_admin());

-- ============================================================
-- Dữ liệu khởi tạo (idempotent — chạy lại an toàn nhờ ON CONFLICT)
-- ============================================================

-- Ngân hàng câu hỏi hiện có, di trú từ services/cnc-lms.ts
on conflict (id) do update set
  quiz_key = excluded.quiz_key,
  question_type = excluded.question_type,
  question = excluded.question,
  options = excluded.options,
  correct_index = excluded.correct_index,
  keywords = excluded.keywords,
  min_keyword_matches = excluded.min_keyword_matches,
  explanation = excluded.explanation,
  order_index = excluded.order_index,
  updated_at = now();

-- Ngân hàng câu hỏi mới: Bài tập 3 (dịch lệnh trả lời ngắn, chấm theo từ khóa)
on conflict (id) do update set
  quiz_key = excluded.quiz_key,
  question_type = excluded.question_type,
  question = excluded.question,
  options = excluded.options,
  correct_index = excluded.correct_index,
  keywords = excluded.keywords,
  min_keyword_matches = excluded.min_keyword_matches,
  explanation = excluded.explanation,
  order_index = excluded.order_index,
  updated_at = now();
